import { FormParams, getParamsFromForm } from "../helpers/utils";

export interface CartItem {
  id: string;
  quantity: number;
  properties: Record<string, string | string[] | Record<string, string>>;
  title: string;
  image: string;
  original_price: string;
  original_line_price: string;
  sku: string;
  product_has_only_default_variant: boolean;
  options_with_values: Record<string, string>[];
  variant_id: string;
  inventory_quantity: number;

  // ....
}

export interface CartData {
  attributes: object;
  cart_level_discount_applications: string[];
  currency: string;
  item_count: number;
  items: CartItem[];
  items_subtotal_price: string;
  note: string | null;
  original_total_price: number;
  requires_shipping: boolean;
  token: string | null;
  total_discount: number;
  total_price: number;
  total_weight: number;

  // ....
}

interface ICart extends HTMLElement {
  cartData: CartData;
}

export class Cart extends HTMLElement implements ICart {
  static get observedAttributes() {
    return ["cart-data"];
  }

  private _cartData: CartData;

  constructor() {
    super();
    this._cartData = {
      attributes: {},
      cart_level_discount_applications: [],
      currency: "",
      item_count: 0,
      items: [],
      items_subtotal_price: "",
      note: null,
      original_total_price: 0,
      requires_shipping: false,
      token: null,
      total_discount: 0,
      total_price: 0,
      total_weight: 0,
    };
    this.updateAttribute(this._cartData);
  }

  connectedCallback() {
    this.fetchCartData();
    const atcForms = document.querySelectorAll("form[data-productForm='true']");
    atcForms.forEach((form) => {
      form.addEventListener("submit", this.handleAtcSubmit.bind(this));
    });
  }

  attributeChangedCallback(name: string, newValue: string) {
    if (name === "cart-data") {
      this._cartData = JSON.parse(newValue);
    }
  }

  get cartData(): CartData {
    return this._cartData;
  }

  set cartData(data: CartData) {
    this._cartData = data;
    this.updateAttribute(data);
  }

  private updateAttribute(data: CartData): void {
    this.setAttribute("cart-data", JSON.stringify(data));
  }

  public async fetchCartData(): Promise<void> {
    const response = await fetch("/cart.js");
    const data: CartData = await response.json();
    this.cartData = data;
  }

  public async handleAtcSubmit(event: Event): Promise<void> {
    event.preventDefault();
    const form = event.target as HTMLFormElement;
    const params = getParamsFromForm(form);
    if (!params.id)
      return console.error("handleAtcSubmit: No variant ID found in form.");
    const quantity = parseInt(params.quantity as string, 10) || 1;
    const selling_plan = params.selling_plan || "";
    const properties = Cart.extractProperties(params);
    this.addItem(params.id.toString(), quantity, properties, selling_plan);
  }

  private static extractProperties(
    params: FormParams,
  ): Record<string, string | string[] | Record<string, string>> {
    const propertyInputKeys = Object.keys(params).filter((key) =>
      key.startsWith("properties"),
    );
    const properties: Record<
      string,
      string | string[] | Record<string, string>
    > = {};
    propertyInputKeys.forEach((key) => {
      const propertyName = key.replace("properties[", "").replace("]", "");
      properties[propertyName] = params[key];
    });
    return properties;
  }

  public addItem(
    id: string,
    quantity = 1,
    properties: Record<string, string | string[] | Record<string, string>> = {},
    selling_plan: string | string[] | Record<string, string> = "",
  ): void {
    if (!id) return console.error("Cart.addItem() : id is required.");
    const item = {
      id,
      quantity,
      properties,
      selling_plan,
    };
    this.sendAddToCart([item]);
    return;
  }

  public addMultipleItems(
    items: {
      id: string;
      quantity: number;
      properties: Record<string, string | string[] | Record<string, string>>;
      selling_plan: string | string[] | Record<string, string>;
    }[],
  ): void {
    if (!items || !items.length)
      return console.error("Cart.addMultipleItems() : items are required.");
    this.sendAddToCart(items);
  }

  private async sendAddToCart(
    items: {
      id: string;
      quantity: number;
      properties: Record<string, string | string[] | Record<string, string>>;
      selling_plan: string | string[] | Record<string, string>;
    }[],
  ): Promise<void> {
    const response = await fetch("/cart/add.js", {
      method: "POST",
      headers: {
        "Content-Type": "application/json; charset=utf-8",
      },
      body: JSON.stringify({ items }),
    });
    const cart = await response.json();
    if (cart.status) {
      console.error(
        `Cart.sendAddToCart() : ${cart.description || cart.message || "Unknown error"}`,
      );
    } else {
      await this.fetchCartData();
      document.dispatchEvent(new CustomEvent("cartUpdated"));
    }
  }

  public addNote(note: string): void {
    const updateBody = { note };
    this.sendCartUpdate(updateBody);
  }

  public addAttribute(key: string, value: string): void {
    const updateBody = { attributes: { [key]: value } };
    this.sendCartUpdate(updateBody);
  }

  public addMultipleAttributes(attributes: Record<string, string>): void {
    const updateBody = { attributes };
    this.sendCartUpdate(updateBody);
  }

  private async sendCartUpdate(
    updateBody: Record<string, Record<string, string> | string>,
  ): Promise<void> {
    const response = await fetch("/cart/update.js", {
      method: "POST",
      headers: {
        "Content-Type": "application/json; charset=utf-8",
      },
      body: JSON.stringify(updateBody),
    });
    const cart = await response.json();
    if (cart.status) {
      console.error(
        `Cart.sendCartUpdate() : ${cart.description || cart.message || "Unknown error"}`,
      );
    } else {
      await this.fetchCartData();
      document.dispatchEvent(new CustomEvent("cartUpdated"));
    }
  }

  public changeItemQuantity(itemId: string | number, quantity: number): void {
    const isNumber = typeof itemId === "number";
    const isString = typeof itemId === "string";
    const idStr = itemId.toString();
    const isNumericString = isString && /^\d+$/.test(idStr);

    // If a numeric string (variant id), use update.js with updates
    if (isNumericString) {
      this.sendCartUpdate({
        updates: { [idStr]: quantity } as unknown as Record<string, string>,
      });
      return;
    }

    // Number => treat as line number; short numeric string => line; other string => line item key via id
    const itemKey = isNumber ? "line" : "id"; // id = line item key per Shopify AJAX API
    const changeBody = {
      [itemKey]: idStr,
      quantity,
    };
    this.sendCartChange(changeBody);
  }

  public changeItemProperties(
    itemId: string | number,
    properties: Record<string, string>,
  ): void {
    if (!properties || Object.keys(properties).length === 0) {
      return console.error(
        "Cart.changeItemProperties() : properties are required and cannot be empty.",
      );
    }
    const isNumber = typeof itemId === "number";
    const idStr = itemId.toString();
    const isNumericString = typeof itemId === "string" && /^\d+$/.test(idStr);
    const isLine = isNumber || (isNumericString && idStr.length < 10);
    const itemKey = isLine ? "line" : "id"; // id = line item key
    const changeBody = {
      [itemKey]: idStr,
      properties,
    };
    this.sendCartChange(changeBody);
  }

  private async sendCartChange(
    changeBody: Record<string, Record<string, string> | string | number>,
  ): Promise<void> {
    const response = await fetch("/cart/change.js", {
      method: "POST",
      headers: {
        "Content-Type": "application/json; charset=utf-8",
      },
      body: JSON.stringify(changeBody),
    });
    if (response.status && response.status !== 200) {
      console.error(
        `Cart.sendCartChange() : ${response.status === 404 ? "Item not in cart" : "Unknown error"}`,
      );
    } else {
      await this.fetchCartData();
      document.dispatchEvent(new CustomEvent("cartUpdated"));
    }
  }
}

customElements.define("uwp-cart", Cart);
